import { IMPACT_DEFECT_LIMIT, } from '@reticlehq/core';
import { PresenterIcon, PRESENTER_ICON_SIZE, hiIconHtml } from './icons/presenter-icons.js';
import { HUD_SURFACE_CLASS } from './chrome/presenter-hud-chrome.js';
import { esc, isSafeDashboardUrl } from './chrome/presenter-safe-html.js';
import { ACCOUNT_SIGNIN_ATTR, ACCOUNT_TEXT, SYNC_BTN_ATTR, accountControlHtml, syncButtonHtml, } from './presenter-account.js';
import { REPORT_PANEL_ATTR, REPORT_ATTR, REPORT_CLOSE_ATTR } from './presenter-config.js';
import { REPORT_LINKS, REPORT_TEXT, buildLinkedInShareUrl, buildReferralText, buildShareText, buildXShareUrl, compactDuration, compactNumber, COVERAGE_LEVELS, CAPABILITY_WORDS, } from './chrome/presenter-report-copy.js';
const SCOPE_ATTR = 'data-reticle-report-scope';
const SCOPE = { PROJECT: 'project', MACHINE: 'machine' };
const SHARE_X_ATTR = 'data-reticle-share-x';
const SHARE_IN_ATTR = 'data-reticle-share-in';
const SHARE_COPY_ATTR = 'data-reticle-share-copy';
const REFER_ATTR = 'data-reticle-refer';
const COPIED_FLASH_MS = 1600;
export function reportPanelHtml() {
    const close = hiIconHtml(PresenterIcon.REMOVE, PRESENTER_ICON_SIZE.MIN);
    return `<div ${REPORT_PANEL_ATTR} class="reticle-report ${HUD_SURFACE_CLASS}" role="region" aria-label="Reticle impact" aria-hidden="true">
    <div class="reticle-report-inner">
      <div class="reticle-report-head">
        <span class="reticle-report-title">${REPORT_TEXT.TITLE}</span>
        <span class="reticle-segmented reticle-report-scopes" role="group" aria-label="${REPORT_TEXT.SCOPE_LABEL}"><button type="button" ${SCOPE_ATTR}="${SCOPE.PROJECT}" aria-pressed="true">${REPORT_TEXT.PROJECT}</button><button type="button" ${SCOPE_ATTR}="${SCOPE.MACHINE}" aria-pressed="false" title="${REPORT_TEXT.GLOBAL_TITLE}">${REPORT_TEXT.GLOBAL}</button></span>
        <button type="button" ${REPORT_CLOSE_ATTR} class="reticle-report-close" title="Close" aria-label="Close impact">${close}</button>
      </div>
      <div class="reticle-report-body" data-reticle-report-body></div>
      <div class="reticle-report-foot" role="group" aria-label="${REPORT_TEXT.SHARE_LABEL}">
        <span class="reticle-report-share-label">${REPORT_TEXT.SHARE_LABEL}</span>
        <button type="button" ${SHARE_X_ATTR} class="reticle-report-share">${REPORT_TEXT.POST_X}</button>
        <button type="button" ${SHARE_IN_ATTR} class="reticle-report-share">${REPORT_TEXT.POST_IN}</button>
        <button type="button" ${SHARE_COPY_ATTR} class="reticle-report-share">${REPORT_TEXT.COPY}</button>
        <button type="button" ${REFER_ATTR} class="reticle-report-share reticle-report-refer">${REPORT_TEXT.REFER}</button>
      </div>
      <div class="reticle-report-links">
        <a data-reticle-link="docs" href="${REPORT_LINKS.DOCS}" target="_blank" rel="noreferrer noopener">Docs</a>
        <a data-reticle-link="github" href="${REPORT_LINKS.GITHUB}" target="_blank" rel="noreferrer noopener">GitHub</a>
        <a data-reticle-link="site" href="${REPORT_LINKS.SITE}" target="_blank" rel="noreferrer noopener">reticle.sh</a>
        <a data-reticle-link="discord" href="${REPORT_LINKS.DISCORD}" target="_blank" rel="noreferrer noopener">Discord</a>
      </div>
    </div>
  </div>`;
}
function card(value, label, basis) {
    const tag = basis === undefined
        ? ''
        : `<span class="reticle-report-basis" title="${basis}">${REPORT_TEXT.ESTIMATE_TAG}</span>`;
    return `<div class="reticle-report-card"><span class="reticle-report-value">${value}</span><span class="reticle-report-label">${label}${tag}</span></div>`;
}
function chart(scope) {
    const days = scope.days.slice(-30);
    if (0 === days.length)
        return '';
    const peak = Math.max(1, ...days.map((d) => d.counts.verdicts));
    const bars = days
        .map((d) => {
        const pct = Math.max(4, Math.round((d.counts.verdicts / peak) * 100));
        const title = `${d.date}: ${String(d.counts.verdicts)} verdicts, ${String(d.counts.failed)} defects`;
        const hot = d.counts.failed > 0 ? ' data-hot="1"' : '';
        return `<span class="reticle-report-bar" style="height:${String(pct)}%" title="${title}"${hot}></span>`;
    })
        .join('');
    return `<div class="reticle-report-chart-wrap"><span class="reticle-report-section">${REPORT_TEXT.CHART}</span><div class="reticle-report-chart">${bars}</div></div>`;
}
function defects(scope, dashboardUrl) {
    const list = (scope.defects ?? []).slice(0, IMPACT_DEFECT_LIMIT);
    if (0 === list.length)
        return '';
    const linked = dashboardUrl !== undefined && isSafeDashboardUrl(dashboardUrl);
    const rowLink = linked
        ? `<a class="reticle-report-defect-link" data-reticle-link="defect" href="${esc(dashboardUrl)}" target="_blank" rel="noreferrer noopener" title="${REPORT_TEXT.DEFECT_LINK_TITLE}" aria-label="${REPORT_TEXT.DEFECT_LINK_TITLE}">${hiIconHtml(PresenterIcon.VIEW, PRESENTER_ICON_SIZE.SEND)}</a>`
        : '';
    const rows = list
        .map((d) => {
        const detail = d.detail === undefined
            ? ''
            : `<span class="reticle-report-defect-detail">${esc(d.detail)}</span>`;
        const source = d.source === undefined
            ? ''
            : `<span class="reticle-report-defect-source">${esc(d.source)}</span>`;
        return `<li class="reticle-report-defect"><span class="reticle-report-defect-title">${esc(d.title)}</span>${detail}${source}${rowLink}</li>`;
    })
        .join('');
    const hidden = scope.counts.failed > list.length;
    const more = !linked
        ? !hidden
            ? ''
            : `<button type="button" data-reticle-defects-all ${ACCOUNT_SIGNIN_ATTR} class="reticle-report-defects-all" title="${REPORT_TEXT.DEFECTS_SEE_ALL_TITLE}">${REPORT_TEXT.DEFECTS_SEE_ALL} (${String(scope.counts.failed)}) →</button>`
        : `<a class="reticle-report-defects-more" data-reticle-link="dashboard" href="${esc(dashboardUrl)}" target="_blank" rel="noreferrer noopener">${REPORT_TEXT.DEFECTS_MORE}${hidden ? ` (${String(scope.counts.failed)})` : ''}</a>`;
    const sync = syncButtonHtml(dashboardUrl);
    return `<div class="reticle-report-defects-wrap"><div class="reticle-report-defects-head"><span class="reticle-report-section">${REPORT_TEXT.DEFECTS}</span>${sync}</div><ul class="reticle-report-defects">${rows}</ul>${more}</div>`;
}
function syncStatusHtml(sync) {
    if (sync === undefined)
        return '';
    const num = (key) => ('number' === typeof sync[key] ? sync[key] : 0);
    const status = sync['status'];
    const keyRefused = 'string' === typeof sync['keyRefused'] ? sync['keyRefused'] : undefined;
    const label = keyRefused !== undefined
        ? REPORT_TEXT.KEY_REFUSED
        : 'refused' === status
            ? `${String(num('refused'))} refused`
            : 'pending' === status
                ? `${String(num('pending'))} waiting`
                : 'on-platform' === status
                    ? `Synced · ${String(num('onPlatform'))}`
                    : 'local-only' === status
                        ? `${String(num('pending'))} ${REPORT_TEXT.NOT_SENT}`
                        : undefined;
    if (label === undefined)
        return '';
    const said = keyRefused !== undefined
        ? keyRefused
        : 'local-only' === status
            ? REPORT_TEXT.NOT_SENT_HELP
            : 'string' === typeof sync['said']
                ? sync['said']
                : '';
    const runUrl = sync['runUrl'];
    const seeRun = 'string' === typeof runUrl && isSafeDashboardUrl(runUrl)
        ? ` <a class="reticle-sync-run" data-reticle-link="run" href="${esc(runUrl)}" target="_blank" rel="noreferrer noopener">${REPORT_TEXT.SEE_RUN}</a>`
        : '';
    return `<span class="reticle-sync-status" data-reticle-sync-status="${esc(String(status))}" title="${esc(said)}">${label}</span>${seeRun}`;
}
const capabilityWords = (name) => 'string' === typeof name ? esc(CAPABILITY_WORDS[name] ?? name) : undefined;
function capabilityItem(state, name, cost = '') {
    const mark = 'seen' === state ? '✓' : 'missing' === state ? '✕' : '○';
    const why = '' === cost ? '' : `<span class="reticle-report-cap-cost">${cost}</span>`;
    return `<li class="reticle-report-cap" data-state="${state}"><span class="reticle-report-cap-mark" aria-hidden="true">${mark}</span><span class="reticle-report-cap-name">${name}</span>${why}</li>`;
}
export function instrumentationHtml(instrumentation) {
    if (instrumentation === undefined)
        return '';
    const covered = instrumentation['covered'];
    const total = instrumentation['total'];
    if ('number' !== typeof covered || 'number' !== typeof total)
        return '';
    const list = (key) => {
        const value = instrumentation[key];
        return Array.isArray(value) ? value : [];
    };
    const seen = list('seen').flatMap((n) => {
        const name = capabilityWords(n);
        return name === undefined ? [] : [capabilityItem('seen', name)];
    });
    const missing = list('missing').flatMap((m) => {
        if ('object' !== typeof m || null === m)
            return [];
        const gap = m;
        const name = capabilityWords(gap['capability']);
        const cost = 'string' === typeof gap['cost'] ? esc(gap['cost']) : '';
        return name === undefined ? [] : [capabilityItem('missing', name, cost)];
    });
    const unseen = list('notSeenYet').flatMap((n) => {
        const name = capabilityWords(n);
        return name === undefined ? [] : [capabilityItem('unseen', name)];
    });
    const items = [...missing, ...seen, ...unseen];
    const caps = 0 === items.length
        ? ''
        : `<ul class="reticle-report-caps">${items.join('')}</ul>${0 === unseen.length ? '' : `<span class="reticle-report-caps-note">○ ${REPORT_TEXT.NOT_SEEN_YET}</span>`}`;
    const copy = 'string' === typeof instrumentation['prompt']
        ? `<button type="button" class="reticle-report-copy-prompt" ${COPY_PROMPT_ATTR}>${REPORT_TEXT.COPY_PROMPT}</button>`
        : '';
    return `<div class="reticle-report-instrumentation" title="${REPORT_TEXT.INSTRUMENTATION_HELP}"><div class="reticle-report-instrumentation-head"><span class="reticle-report-section">${REPORT_TEXT.INSTRUMENTATION}</span><span class="reticle-report-instrumentation-value">${REPORT_TEXT.covered(Math.round(covered), Math.round(total))}</span></div>${caps}${copy}</div>`;
}
const COPY_PROMPT_ATTR = 'data-reticle-copy-prompt';
function coverageHtml(coverage) {
    if (coverage === undefined)
        return '';
    const known = COVERAGE_LEVELS.filter((l) => 'number' === typeof coverage[l.key]);
    if (0 === known.length)
        return '';
    const pct = (key) => `${String(Math.round(coverage[key] ?? 0))}%`;
    const head = 'number' === typeof coverage['proved'] ? pct('proved') : pct(known[0]?.key ?? '');
    const rows = known
        .map((l) => `<span class="reticle-report-coverage-level">${pct(l.key)} ${l.label}</span>`)
        .join('');
    return `<div class="reticle-report-coverage" title="${REPORT_TEXT.COVERAGE_HELP}"><span class="reticle-report-section">${REPORT_TEXT.COVERAGE}</span><span class="reticle-report-coverage-value">${head}</span><div class="reticle-report-coverage-levels">${rows}</div></div>`;
}
export function reportBodyHtml(scope, dashboardUrl, account, projectName, coverage, sync, instrumentation) {
    const c = scope.counts;
    if (0 === c.calls)
        return `<p class="reticle-report-empty">${REPORT_TEXT.EMPTY}</p>`;
    const streak = scope.records.streakDays > 0
        ? `<span class="reticle-report-streak" title="Consecutive days with at least one verdict">🔥 ${String(scope.records.streakDays)} <span class="reticle-report-streak-label">${REPORT_TEXT.STREAK}</span></span>`
        : '';
    const hero = `<div class="reticle-report-hero"><span class="reticle-report-hero-value">${compactNumber(c.failed)}</span><span class="reticle-report-hero-label">${REPORT_TEXT.heroDefects(c.failed)}</span></div>`;
    const verdicts = `<div class="reticle-report-verdicts" title="${REPORT_TEXT.UNKNOWN_HELP}">
    <span class="reticle-report-verdict" data-kind="pass">${compactNumber(c.passed)} ${REPORT_TEXT.PASSED}</span>
    <span class="reticle-report-verdict" data-kind="fail">${compactNumber(c.failed)} ${REPORT_TEXT.FAILED}</span>
    <span class="reticle-report-verdict" data-kind="unknown">${compactNumber(c.unknown)} ${REPORT_TEXT.UNKNOWN}</span>
  </div>`;
    const cards = [
        card(compactNumber(c.verdicts), REPORT_TEXT.VERDICTS),
        card(compactNumber(c.calls), REPORT_TEXT.CALLS),
        card(compactDuration(c.drivingMs), REPORT_TEXT.DRIVING),
        card(compactNumber(c.sessions), REPORT_TEXT.SESSIONS),
        card(compactDuration(scope.records.longestRunMs), REPORT_TEXT.LONGEST),
        card(compactNumber(c.tokensReturned), REPORT_TEXT.TOKENS),
        card(compactNumber(scope.savings.tokens.value), REPORT_TEXT.SAVED_TOKENS, scope.savings.tokens.basis),
        card(compactDuration(scope.savings.minutes.value * 60_000), REPORT_TEXT.SAVED_MINUTES, scope.savings.minutes.basis),
    ].join('');
    const identity = `<div class="reticle-report-identity">${accountControlHtml(account, { dashboardUrl, projectName, verdicts: c.verdicts, defects: c.failed })}${syncButtonHtml(dashboardUrl)}${syncStatusHtml(sync)}</div>`;
    return `<div class="reticle-report-top">${streak}${identity}</div>${hero}${verdicts}${instrumentationHtml(instrumentation)}${coverageHtml(coverage)}<div class="reticle-report-grid">${cards}</div>${defects(scope, dashboardUrl)}${chart(scope)}${localOnly(scope, dashboardUrl, account)}`;
}
function localOnly(scope, dashboardUrl, account) {
    if (dashboardUrl !== undefined)
        return '';
    if (scope.counts.verdicts <= 0)
        return '';
    if (account === undefined)
        return '';
    const [lead, action, tail] = account.signedIn
        ? [REPORT_TEXT.UNLINKED, REPORT_TEXT.UNLINKED_ACTION, REPORT_TEXT.UNLINKED_TAIL]
        : [REPORT_TEXT.LOCAL_ONLY, REPORT_TEXT.LOCAL_ONLY_ACTION, REPORT_TEXT.LOCAL_ONLY_TAIL];
    return `<p class="reticle-report-local-only">${lead} <code>${action}</code> ${tail}</p>`;
}
const SYNC_SPIN_MS = 1_200;
const SYNCING_ATTR = 'data-syncing';
export class PresenterReport {
    #panel;
    #body;
    #root;
    #snapshot;
    #global = false;
    #host;
    constructor(host = {}) {
        this.#host = host;
    }
    mount(root) {
        this.#root = root;
        this.#panel = root.querySelector(`[${REPORT_PANEL_ATTR}]`) ?? undefined;
        this.#body = root.querySelector('[data-reticle-report-body]') ?? undefined;
        root.querySelector(`[${REPORT_CLOSE_ATTR}]`)?.addEventListener('click', (e) => {
            e.stopPropagation();
            this.close();
        });
        const scopeBtns = root.querySelectorAll(`[${SCOPE_ATTR}]`);
        for (const btn of scopeBtns) {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                this.#global = SCOPE.MACHINE === btn.getAttribute(SCOPE_ATTR);
                for (const other of scopeBtns) {
                    other.setAttribute('aria-pressed', other === btn ? 'true' : 'false');
                }
                this.#paint();
            });
        }
        root.querySelector(`[${SHARE_X_ATTR}]`)?.addEventListener('click', (e) => {
            e.stopPropagation();
            this.#openShare(buildXShareUrl(this.shareText()));
        });
        root.querySelector(`[${SHARE_IN_ATTR}]`)?.addEventListener('click', (e) => {
            e.stopPropagation();
            void this.#copy(this.shareText());
            this.#openShare(buildLinkedInShareUrl());
        });
        root.querySelector(`[${SHARE_COPY_ATTR}]`)?.addEventListener('click', (e) => {
            e.stopPropagation();
            void this.#copy(this.shareText(), e.currentTarget);
        });
        root.querySelector(`[${REFER_ATTR}]`)?.addEventListener('click', (e) => {
            e.stopPropagation();
            void this.#copy(buildReferralText(), e.currentTarget);
        });
        root.addEventListener('click', (e) => {
            const target = e.target;
            if (!(target instanceof Element))
                return;
            const signin = target.closest(`[${ACCOUNT_SIGNIN_ATTR}]`);
            if (signin !== null) {
                e.stopPropagation();
                void this.#copy(ACCOUNT_TEXT.SIGNIN_COMMAND, signin);
                return;
            }
            const copyPrompt = target.closest(`[${COPY_PROMPT_ATTR}]`);
            const prompt = this.#snapshot?.instrumentation?.['prompt'];
            if (copyPrompt !== null && 'string' === typeof prompt) {
                e.stopPropagation();
                void this.#copy(prompt, copyPrompt);
                return;
            }
            const sync = target.closest(`[${SYNC_BTN_ATTR}]`);
            if (sync !== null) {
                e.stopPropagation();
                this.#host.onSyncNow?.();
                sync.setAttribute(SYNCING_ATTR, '1');
                setTimeout(() => sync.removeAttribute(SYNCING_ATTR), SYNC_SPIN_MS);
            }
        });
    }
    setSnapshot(snapshot) {
        this.#snapshot = snapshot;
        if (this.isOpen())
            this.#paint();
    }
    snapshot() {
        return this.#snapshot;
    }
    isOpen() {
        return '1' === this.#root?.getAttribute(REPORT_ATTR);
    }
    open() {
        if (this.#root === undefined)
            return;
        this.#host.onBeforeOpen?.();
        this.#paint();
        this.#root.setAttribute(REPORT_ATTR, '1');
        this.#panel?.setAttribute('aria-hidden', 'false');
    }
    close() {
        this.#root?.setAttribute(REPORT_ATTR, '0');
        this.#panel?.setAttribute('aria-hidden', 'true');
    }
    toggle() {
        if (this.isOpen())
            this.close();
        else
            this.open();
    }
    contains(node) {
        return true === this.#panel?.contains(node);
    }
    shareText() {
        const snap = this.#snapshot;
        if (snap === undefined)
            return buildReferralText();
        return this.#global
            ? buildShareText(snap.global)
            : buildShareText(snap.project, snap.projectName);
    }
    #scope() {
        const snap = this.#snapshot;
        if (snap === undefined)
            return undefined;
        return this.#global ? snap.global : snap.project;
    }
    #paint() {
        const scope = this.#scope();
        if (this.#body === undefined)
            return;
        this.#body.innerHTML =
            scope === undefined
                ? `<p class="reticle-report-empty">${REPORT_TEXT.EMPTY}</p>`
                : reportBodyHtml(scope, this.#snapshot?.dashboardUrl, this.#snapshot?.account, this.#snapshot?.projectName, this.#global ? undefined : this.#snapshot?.coverage, this.#global ? undefined : this.#snapshot?.sync, this.#global ? undefined : this.#snapshot?.instrumentation);
    }
    #openShare(url) {
        window.open(url, '_blank', 'noopener,noreferrer');
    }
    async #copy(text, button) {
        try {
            await navigator.clipboard?.writeText(text);
        }
        catch {
        }
        if (button instanceof HTMLElement) {
            const original = button.textContent ?? '';
            button.textContent = REPORT_TEXT.COPIED;
            window.setTimeout(() => {
                button.textContent = original;
            }, COPIED_FLASH_MS);
        }
    }
}
