import { ReticleStorageKey } from '../../storage-keys.js';
const LOG_STORAGE_KEY = ReticleStorageKey.PRESENTER_LOG;
export function readRememberedLog() {
    try {
        const raw = JSON.parse(globalThis.sessionStorage.getItem(LOG_STORAGE_KEY) ?? '[]');
        return Array.isArray(raw)
            ? raw.filter((row) => 'object' === typeof row &&
                null !== row &&
                'string' === typeof row.text &&
                'string' === typeof row.kind &&
                'string' === typeof row.ts &&
                'number' === typeof row.at)
            : [];
    }
    catch {
        return [];
    }
}
export function rememberLog(rows) {
    try {
        globalThis.sessionStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(rows));
    }
    catch {
    }
}
export function claimLog(owner) {
    try {
        const now = owner ?? '';
        const before = globalThis.sessionStorage.getItem(ReticleStorageKey.PRESENTER_LOG_OWNER);
        globalThis.sessionStorage.setItem(ReticleStorageKey.PRESENTER_LOG_OWNER, now);
        if (null === before || before === now)
            return false;
        globalThis.sessionStorage.removeItem(LOG_STORAGE_KEY);
        return true;
    }
    catch {
        return false;
    }
}
